const $=(s)=>document.querySelector(s); const api=async(p,o={})=>{const r=await fetch(p,{headers:{'Content-Type':'application/json'},...o}); const b=await r.json(); if(!r.ok) throw new Error(b.error||'Failed'); return b;};
