 if(location.pathname==='/finance/journal/new'){ $('#title').textContent='New Journal Entry'; v.innerHTML=`<form id='newJe' class='card wide'><div class='header-row'><h3>New Journal Entry</h3><div><button type='button' id='saveDoc'>Save</button><button type='button' id='postJe'>Post</button></div></div><label>Post Date<input id='jd' type='date' value='${new Date().toISOString().slice(0,10)}' required></label><label>Post Period<input id='jp' value='${new Date().toISOString().slice(0,7)}' readonly></label><label>Description<input id='jdesc'></label><table id='jlines'><tr><th>Branch</th><th>Branch Code</th><th>Account</th><th>Debit</th><th>Credit</th><th>Reference</th></tr></table><button type='button' id='addJl'>Add Line</button></form>`; const branches=await api('/api/finance/branches'); const coa=await api('/api/finance/chart-of-accounts'); const acctOpts=coa.map(a=>`<option value='${a.accountNumber}'>${a.accountNumber} - ${a.accountTitle}</option>`).join(''); const addRow=()=>$('#jlines').insertAdjacentHTML('beforeend',`<tr><td><select class='bname'>${branches.map(b=>`<option value='${b.code}'>${b.name}</option>`)}</select></td><td><input class='bcode' value='100'></td><td><select class='acctSel'>${acctOpts}</select></td><td><input class='dr' type='number' value='0'></td><td><input class='cr' type='number' value='0'></td><td><input class='ref'></td></tr>`); addRow(); addRow(); let saved=null; $('#addJl').onclick=addRow; const calcJePeriod=()=>{$('#jp').value=($('#jd').value||new Date().toISOString().slice(0,10)).slice(0,7);}; $('#jd').onchange=calcJePeriod; calcJePeriod(); const saveJe=async()=>{ const lines=[...document.querySelectorAll('#jlines tr')].slice(1).map(r=>({branch:r.querySelector('.bcode').value||r.querySelector('.bname').value,account:r.querySelector('.acctSel').value,debit:Number(r.querySelector('.dr').value||0),credit:Number(r.querySelector('.cr').value||0),sourceReference:r.querySelector('.ref').value})); saved=await api('/api/finance/journal-transactions',{method:'POST',body:JSON.stringify({transactionDate:$('#jd').value,financialPeriod:$('#jp').value,description:$('#jdesc').value,lines})}); alert('Saved '+saved.jeNumber); history.pushState({},'',`/finance/journal/${saved.jeNumber}`); router();}; $('#saveDoc').onclick=saveJe; $('#postJe').onclick=async()=>{if(!saved) return alert('Save first'); await api('/api/finance/journal-transactions/post',{method:'POST',body:JSON.stringify({jeNumber:saved.jeNumber})}); router();}; return; }
